var re = /^app_duration_bucket\{[^}]*le="([0-9.]+|\+Inf)"[^}]*\}\s+([0-9eE\+\-\.]+)/gm;
var buckets = [];
var match;
var totalCount = 0;

while ((match = re.exec(text)) !== null) {
    var le = match[1] === '+Inf' ? Infinity : parseFloat(match[1]);
    var count = parseFloat(match[2]);
    buckets.push({ le: le, count: count });
    totalCount = Math.max(totalCount, count);
}

if (buckets.length === 0) { throw 'app_duration_bucket nao encontrado'; }

buckets.sort(function(a, b) { return a.le - b.le; });
var target = totalCount * 0.95;

for (var i = 0; i < buckets.length; i++) {
    if (buckets[i].count >= target) {
        return buckets[i].le === Infinity ? buckets[buckets.length - 2].le : buckets[i].le;
    }
}

return buckets[buckets.length - 1].le;
